use vstd::prelude::*;

verus! {

spec fn flipud_seq(s: Seq<f32>) -> Seq<f32> {
    Seq::new(s.len(), |i: int| s[s.len() - 1 - i])
}

fn flipud(m: Vec<f32>) -> (result: Vec<f32>)
    ensures
        result@ == flipud_seq(m@),
        result.len() == m.len(),
{
    let n = m.len();
    let mut result = Vec::with_capacity(n);

    for i in 0..n
        invariant
            n == m.len(),
            result.len() == i,
            result@ == flipud_seq(m@).subrange(0, i as int),
        decreases n - i,
    {
        // Array bounds needed for indexing m[n - 1 - i]
        assert(i < n);
        assert(n - 1 - i < n);

        result.push(m[n - 1 - i]);

        // Help the verifier connect the pushed element to the spec sequence
        assert(result@ == flipud_seq(m@).subrange(0, (i + 1) as int));
    }

    result
}

} // verus!

